import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.DQ-7HQaQ.js";const p=JSON.parse('{"title":"Evaluate and explain your RAG","description":"Five source-grounded evaluation questions, meaningful checks and a simple human peer-review routine.","frontmatter":{"title":"Evaluate and explain your RAG","description":"Five source-grounded evaluation questions, meaningful checks and a simple human peer-review routine."},"headers":[],"relativePath":"students/check.md","filePath":"students/check.md","lastUpdated":1794376220000}'),n={name:"students/check.md"};function s(i,e,d,h,c,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="check-the-system-not-just-the-chatbot" tabindex="-1">Check the system, not just the chatbot <a class="header-anchor" href="#check-the-system-not-just-the-chatbot" aria-label="Permalink to &quot;Check the system, not just the chatbot&quot;">​</a></h1><p>A fluent answer is not proof of a good retrieval system. Write what evidence you expect <em>before</em> generating answers. Record actual outputs and compare them with the original sources.</p><h2 id="five-questions-to-prepare" tabindex="-1">Five questions to prepare <a class="header-anchor" href="#five-questions-to-prepare" aria-label="Permalink to &quot;Five questions to prepare&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>Example using fictional club policies</th><th>What you inspect</th></tr></thead><tbody><tr><td>Exact term</td><td>What is the membership fee?</td><td>Can retrieval find the named policy?</td></tr><tr><td>Paraphrase</td><td>How does a new member ask for help?</td><td>Can retrieval find equivalent wording?</td></tr><tr><td>Relationship</td><td>Which committee organizes events?</td><td>Does your chosen representation preserve the relationship?</td></tr><tr><td>Practical</td><td>What should a visitor do before attending?</td><td>Are all important claims supported?</td></tr><tr><td><strong>Unanswerable</strong></td><td>What is the date of next year&#39;s annual meeting?</td><td>Does the system admit missing evidence rather than invent it?</td></tr></tbody></table><p>Replace these with <strong>your own domain&#39;s</strong> questions; the examples are not an answer key. A relationship question may be answered from text even without a graph. Don&#39;t pretend a tiny evaluation set measures general product quality.</p><h2 id="record-one-row-per-question" tabindex="-1">Record one row per question <a class="header-anchor" href="#record-one-row-per-question" aria-label="Permalink to &quot;Record one row per question&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Write down</th></tr></thead><tbody><tr><td>Question and expected source IDs</td><td>Prediction made before querying</td></tr><tr><td>Retrieved source/chunk IDs or graph paths</td><td>Actual observed output, not a screenshot of an AI explanation</td></tr><tr><td>Generated answer and model/provider</td><td>Real execution, identifiable version where available</td></tr><tr><td>Citation quality</td><td>Did the cited passage actually support the particular claim?</td></tr><tr><td>Failure and change</td><td>What broke? What did you change and retest?</td></tr></tbody></table><p><strong>Test import twice.</strong> Check stored IDs/counts after repeated identical sources and after one edited source. <strong>Test access.</strong> A public visitor should not be able to import, delete, inspect secrets or use administrative endpoints.</p><h2 id="peer-walkthrough" tabindex="-1">Peer walkthrough <a class="header-anchor" href="#peer-walkthrough" aria-label="Permalink to &quot;Peer walkthrough&quot;">​</a></h2><p>Ask a real classmate to open the hosted app without a narrated tour. Have them ask one supported question and one missing-evidence question, then open a reference. Record their actual confusion or failure, make a bounded change, and rerun the same test. An AI role-play can prepare you but is <strong>not</strong> real peer review.</p><h2 id="explain-your-choices" tabindex="-1">Explain your choices <a class="header-anchor" href="#explain-your-choices" aria-label="Permalink to &quot;Explain your choices&quot;">​</a></h2><p>Be able to say why you chose vector, graph or hybrid retrieval; what chunking, identity and source metadata mean; what an embedding represents; what the database stores; what a model generates; and how you know an answer is or isn&#39;t supported.</p><p>At Demo Day, show <strong>problem → real app → source/retrieval/answer trace → actual checks → individual contribution</strong>. The <a href="https://github.com/kaw393939/is373-studio/blob/main/docs/course/milestones.md" target="_blank" rel="noreferrer">course milestones</a> and Canvas control official submissions and grading.</p><p><a href="./prompts#demo-prompt">Copy an evaluation agent prompt</a> · <a href="./">Back to student guide</a></p>',14)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
